drop policy if exists availability_professional_insert on public.availability_slots;
drop policy if exists availability_professional_update on public.availability_slots;
drop policy if exists availability_professional_delete on public.availability_slots;
create policy availability_professional_insert on public.availability_slots for insert to authenticated with check (((professional_id = (select auth.uid())) and (select public.jwt_app_role()) = 'professional' and exists (select 1 from public.professional_profiles p where p.user_id = (select auth.uid()) and p.status = 'approved')) or (select public.jwt_app_role()) = 'admin');
create policy availability_professional_update on public.availability_slots for update to authenticated using (((professional_id = (select auth.uid())) and (select public.jwt_app_role()) = 'professional' and exists (select 1 from public.professional_profiles p where p.user_id = (select auth.uid()) and p.status = 'approved')) or (select public.jwt_app_role()) = 'admin') with check (((professional_id = (select auth.uid())) and (select public.jwt_app_role()) = 'professional' and exists (select 1 from public.professional_profiles p where p.user_id = (select auth.uid()) and p.status = 'approved')) or (select public.jwt_app_role()) = 'admin');
create policy availability_professional_delete on public.availability_slots for delete to authenticated using (((professional_id = (select auth.uid())) and (select public.jwt_app_role()) = 'professional' and exists (select 1 from public.professional_profiles p where p.user_id = (select auth.uid()) and p.status = 'approved')) or (select public.jwt_app_role()) = 'admin');
drop policy if exists clinical_records_professional_update on public.clinical_records;
create policy clinical_records_professional_update on public.clinical_records for update to authenticated using ((professional_id = (select auth.uid()) and (select public.jwt_app_role()) = 'professional') or (select public.jwt_app_role()) = 'admin') with check ((professional_id = (select auth.uid()) and (select public.jwt_app_role()) = 'professional') or (select public.jwt_app_role()) = 'admin');